(()=>{'use strict';const BRIDGE='http://127.0.0.1:8767';let pdf=null,pageNo=1,file=null;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));async function bridge(path,body){const r=await fetch(BRIDGE+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(await r.text());return r.json()}async function loadPdf(){if(!file)return;const bytes=new Uint8Array(await file.arrayBuffer());const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.worker.min.mjs';pdf=await pdfjs.getDocument({data:bytes}).promise;pageNo=1;$('#pdfPage').max=pdf.numPages;$('#pdfPage').value=1;$('#pdfInfo').innerHTML='<span>'+esc(file.name)+'</span><span>'+pdf.numPages+' pages</span><span>'+Math.round(file.size/1024)+' KB</span>';$('#pdfEmpty').style.display='none';await renderPage();$('#pdfStatus').textContent='PDF loaded · '+pdf.numPages+' pages'}async function renderPage(){if(!pdf)return;pageNo=Math.max(1,Math.min(pdf.numPages,Number($('#pdfPage').value)||1));$('#pdfPage').value=pageNo;const p=await pdf.getPage(pageNo);const zoom=Number($('#pdfZoom').value||1);const base=p.getViewport({scale:1});const maxWidth=Math.max(300,$('.pdf-viewer').clientWidth-36);const scale=zoom===1?Math.min(1.5,maxWidth/base.width):zoom;const v=p.getViewport({scale});const c=$('#pdfCanvas');c.width=Math.ceil(v.width);c.height=Math.ceil(v.height);await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise}async function extract(){if(!file)return;try{const b=await file.arrayBuffer();const encoded=btoa(String.fromCharCode(...new Uint8Array(b)));const r=await bridge('/pdf/read',{filename:file.name,pdf:encoded});$('#pdfText').textContent=r.text||'(No extractable text)';$('#pdfInfo').innerHTML+='<span>PyPDF: '+esc(r.pages)+' pages</span>'}catch(e){$('#pdfText').textContent='Local PyPDF bridge unavailable. The PDF is still fully visible above. Start tools/pdf-reader/bridge.py locally for text extraction.'}}$('#pdfFile').onchange=()=>{file=$('#pdfFile').files[0];if(file)loadPdf().catch(e=>$('#pdfStatus').textContent='PDF load error: '+e.message)};$('#pdfOpen').onclick=()=>loadPdf().catch(e=>$('#pdfStatus').textContent='PDF load error: '+e.message);$('#pdfPage').onchange=renderPage;$('#pdfZoom').onchange=renderPage;$('#pdfPrev').onclick=()=>{if(pdf){pageNo--;renderPage()}};$('#pdfNext').onclick=()=>{if(pdf){pageNo++;renderPage()}};$('#pdfFit').onclick=()=>{$('#pdfZoom').value='1';renderPage()};$('#pdfExtract').onclick=extract;window.addEventListener('resize',()=>pdf&&renderPage());})();